{
  "arguments": [
    {
      "claim": "The artillery attacks on Knin, Benkovac, Obrovac and Gračac violated the principle of distinction because they were directed at areas where civilians were concentrated and no verifiable military objectives were identified.",
      "reasoning": "International humanitarian law requires that attacks be directed solely at military objectives. The Trial Chamber found that the HV could not identify any targets of opportunity within the towns and applied a 200‑metre margin, treating impacts beyond that distance as evidence of unlawful attacks. This factual finding satisfies the legal requirement that attacks on civilian objects are prohibited, as reflected in the Rome Statute’s prohibition of attacks on undefended towns that are not military objectives.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "(v) Attacking or bombarding, by whatever means, towns, villages, dwellings or buildings which are undefended and which are not military objectives;"
        }
      ]
    },
    {
      "claim": "The attacks were disproportionate because the expected civilian harm, including large‑scale displacement and civilian casualties, was clearly excessive in relation to any concrete and direct military advantage that could be gained.",
      "reasoning": "The principle of proportionality bars attacks in which the incidental civilian loss would be excessive compared with the anticipated military gain. The Chamber’s evidence of massive civilian flight and the inability to identify legitimate targets demonstrates that the anticipated advantage was minimal, while the civilian harm was substantial, satisfying the proportionality test under the Rome Statute’s prohibition of extensive destruction not justified by military necessity.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "(iv) Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    },
    {
      "claim": "The use of artillery in densely populated areas without taking all feasible precautions breached the specific prohibitions of CCW Protocol III on attacks against military objectives located within concentrations of civilians.",
      "reasoning": "Protocol III expressly forbids attacks on military objectives situated within civilian concentrations unless all feasible precautions are taken to limit incidental loss of life. The evidence shows no such precautions were implemented; impact sites were frequently more than 200 metres from any verified military target, indicating a failure to verify targets and to minimize civilian harm, thereby violating the protocol.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccw_p_iii",
          "article": "2(3)",
          "quoted_text": "It is further prohibited to make any military objective located within a concentration of civilians the object of attack by means of incendiary weapons other than air-delivered incendiary weapons, except when such military objective is clearly separated from the concentration of civilians and all feasible precautions are taken with a view to limiting the incendiary effects to the military objective and to avoiding, and in any event to minimizing, incidental loss of civilian life, injury to civilians and damage to civilian objects."
        },
        {
          "type": "treaty",
          "instrument": "ccw_p_iii",
          "article": "2(2)",
          "quoted_text": "It is prohibited in all circumstances to make any military objective located within a concentration of civilians the object of attack by air-delivered incendiary weapons."
        }
      ]
    },
    {
      "claim": "Beyond reasonable doubt, the artillery attacks constitute war crimes under the Rome Statute because they amount to intentional attacks on civilian objects and extensive, unjustified destruction of property.",
      "reasoning": "Article 8(2)(b)(iv) and (v) of the Rome Statute enumerate war crimes that include extensive destruction not justified by military necessity and attacks on undefended towns. The factual record—absence of identifiable military targets, large civilian displacement, and indiscriminate impact locations—fulfills the elements of these crimes, meeting the standard of proof beyond reasonable doubt.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "(iv) Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "(v) Attacking or bombarding, by whatever means, towns, villages, dwellings or buildings which are undefended and which are not military objectives;"
        }
      ]
    }
  ]
}

